-- GENERATED by `cargo run -p arlesh-core --example generate_baseline`. Do not edit.
-- The schema and seed data that migrations 1 through 111 leave behind: a fresh
-- database is created from this in one pass, then migrations 1..=111 are recorded as
-- applied. See src/database/baseline.rs. A unit test fails on any difference from the chain.

CREATE TABLE undo_context (
    id         INTEGER PRIMARY KEY CHECK (id = 1),
    gesture_id TEXT,
    depth      INTEGER NOT NULL DEFAULT 0 CHECK (depth >= 0),
    source     TEXT NOT NULL DEFAULT 'user',
    suppressed INTEGER NOT NULL DEFAULT 0 CHECK (suppressed IN (0, 1)), client TEXT NOT NULL DEFAULT 'desktop',
    CHECK ((gesture_id IS NULL) = (depth = 0))
);
CREATE TABLE undo_journal (
    seq          INTEGER PRIMARY KEY AUTOINCREMENT,
    gesture_id   TEXT,
    source       TEXT NOT NULL,
    table_name   TEXT NOT NULL,
    row_id       INTEGER NOT NULL,
    operation    TEXT NOT NULL CHECK (operation IN ('insert', 'update', 'delete')),
    before_image TEXT,
    after_image  TEXT,
    written_at   TEXT NOT NULL, client TEXT NOT NULL DEFAULT 'desktop',
    -- An insert has nothing before it and a delete has nothing after it; an update has both.
    CHECK ((operation = 'insert') = (before_image IS NULL)),
    CHECK ((operation = 'delete') = (after_image IS NULL))
);
CREATE TABLE server_tokens (
    client     TEXT PRIMARY KEY NOT NULL,
    sha256     TEXT NOT NULL UNIQUE,
    created_at TEXT NOT NULL
, last_seen_at TEXT);
CREATE TABLE pairing_pins (
    id_sha256     TEXT PRIMARY KEY NOT NULL,
    pin           TEXT NOT NULL UNIQUE,
    -- The name the device suggested, already reduced to a client name.
    name          TEXT NOT NULL,
    -- The name the approver settled on; NULL until the PIN is approved.
    approved_name TEXT,
    -- Wrong PINs presented with this request's id.
    attempts      INTEGER NOT NULL DEFAULT 0,
    created_at    TEXT NOT NULL,
    expires_at    TEXT NOT NULL
);
CREATE TABLE push_devices (
    client        TEXT PRIMARY KEY NOT NULL,
    -- The device's FCM registration token. One token belongs to one device.
    fcm_token     TEXT NOT NULL,
    registered_at TEXT NOT NULL
);
CREATE TABLE push_sent (
    client  TEXT NOT NULL,
    key     TEXT NOT NULL,
    value   TEXT NOT NULL DEFAULT '',
    sent_at TEXT NOT NULL,
    PRIMARY KEY (client, key)
);
CREATE TABLE agent_pins (
    pin        TEXT PRIMARY KEY NOT NULL,
    created_at TEXT NOT NULL,
    expires_at TEXT NOT NULL
);
CREATE TABLE agent_pin_failures (
    failed_at TEXT NOT NULL
);
CREATE TABLE agent_accounts (
    label  TEXT PRIMARY KEY NOT NULL,
    locked INTEGER NOT NULL DEFAULT 0 CHECK (locked IN (0, 1))
);
CREATE TABLE agent_account_usage (
    account      TEXT NOT NULL,
    window_kind  TEXT NOT NULL,
    percent_used REAL NOT NULL,
    resets_at    TEXT NOT NULL,
    reported_at  TEXT NOT NULL,
    PRIMARY KEY (account, window_kind)
);
CREATE TABLE connect_tokens (
    id           INTEGER PRIMARY KEY CHECK (id = 1),
    sha256       TEXT NOT NULL UNIQUE,
    created_at   TEXT NOT NULL,
    last_used_at TEXT
);
CREATE TABLE agents (
    id           INTEGER PRIMARY KEY AUTOINCREMENT,
    -- What Settings -> Agents shows. Unique, so a name points at one agent.
    name         TEXT NOT NULL UNIQUE,
    -- The label of the account the agent works under; usage is kept per account.
    account      TEXT NOT NULL,
    -- The client's own session id, as the agent last attached with it.
    session_uuid TEXT NOT NULL,
    -- The agent token's digest: what lets a session attach again after a restart.
    token_sha256 TEXT NOT NULL UNIQUE,
    -- The Claim's root, keyed as `mcp_roots` keys a node; both NULL when the agent holds none.
    claim_kind   TEXT,
    claim_id     TEXT,
    -- A paused Claim leaves the subtree free for another agent to claim; the agent keeps its token.
    claim_paused INTEGER NOT NULL DEFAULT 0 CHECK (claim_paused IN (0, 1)),
    -- When the Claim was made: the older of two overlapping Claims keeps its place.
    claimed_at   TEXT,
    -- A manual lock: the agent's claimed Agentic Tasks read blocked while it is on.
    locked       INTEGER NOT NULL DEFAULT 0 CHECK (locked IN (0, 1)),
    created_at   TEXT NOT NULL,
    last_seen_at TEXT, parent_id INTEGER,
    CHECK ((claim_kind IS NULL) = (claim_id IS NULL) AND (claim_kind IS NULL) = (claimed_at IS NULL))
);
CREATE TABLE block_reasons (
    id          TEXT PRIMARY KEY NOT NULL DEFAULT (lower(substr(printf('%012x', cast((julianday('now') - 2440587.5) * 86400000 as integer)), 1, 8) || '-' || substr(printf('%012x', cast((julianday('now') - 2440587.5) * 86400000 as integer)), 9, 4) || '-7' || substr(hex(randomblob(2)), 2, 3) || '-' || substr('89ab', 1 + (abs(random()) % 4), 1) || substr(hex(randomblob(2)), 2, 3) || '-' || hex(randomblob(6)))),
    owner_type  TEXT NOT NULL CHECK (owner_type IN ('task', 'goal')),
    owner_id    TEXT NOT NULL,
    reason      TEXT NOT NULL,
    position    INTEGER NOT NULL DEFAULT 0,
    created_at  TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE "commitments" (
    id                       TEXT PRIMARY KEY NOT NULL DEFAULT (lower(substr(printf('%012x', cast((julianday('now') - 2440587.5) * 86400000 as integer)), 1, 8) || '-' || substr(printf('%012x', cast((julianday('now') - 2440587.5) * 86400000 as integer)), 9, 4) || '-7' || substr(hex(randomblob(2)), 2, 3) || '-' || substr('89ab', 1 + (abs(random()) % 4), 1) || substr(hex(randomblob(2)), 2, 3) || '-' || hex(randomblob(6)))),
    title                    TEXT NOT NULL,
    parent_type              TEXT NOT NULL
                                 CHECK (parent_type IN ('domain', 'goal', 'task', 'commitment')),
    parent_id                TEXT NOT NULL,
